fn push_rules_rule_6494(rules: &mut Vec<RubiRule>) {
    rubi_symb!(a__, b__, c__, d__, e__, p_, x_);
    rules.push(rubi_rule!(
        order: 6494,
        source: "Int[(a_.+b_.*ArcTanh[c_.*x_])^p_./(x_*(d_+e_.*x_)),x_Symbol] :=
          (a+b*ArcTanh[c*x])^p*Log[2-2/(1+e*x/d)]/d -
          b*c*p/d \\[Star] Int[(a+b*ArcTanh[c*x])^(p-1)*Log[2-2/(1+e*x/d)]/(1-c^2*x^2),x] /;
        FreeQ[{a,b,c,d,e},x] && IGtQ[p,0] && EqQ[c^2*d^2-e^2,0]",
        desc: "Integration by parts",
        refs: [],
        pattern: (a__ + b__ * (c__ * x_).atanh()).pow(p_) / (x_ * (d__ + e__ * x_)),
        with: [a__, b__, c__, p_, d__, e__, x_],
        optional: [a__, b__, c__, p_, e__],
        when: {
            freeq!([a__, b__, c__, d__, e__], x_)
                && igtq!(p_, 0)
                && eqq!(c__.pow(2) * d__.pow(2) - e__.pow(2), 0)
        },
        rhs: {
            let argument = &a__ + &b__ * (&c__ * x_).atanh();
            let logarithm = (Atom::num(2) - Atom::num(2) / (Atom::num(1) + &e__ * x_ / &d__)).log();
            let recursive = argument.pow(&p_ - 1) * &logarithm
                / (Atom::num(1) - c__.pow(2) * x_.pow(2));
            rubi_simp(&(argument.pow(&p_) * logarithm / &d__), x_)
                    - rubi_star(&b__ * &c__ * &p_ / &d__, rubi_rhs_int(&recursive, x_))
        },
    ));
}

