fn push_rules_rule_6783(rules: &mut Vec<RubiRule>) {
    rubi_symb!(symbols; u__, v_, n_);
    rules.push(rubi_rule!(
        order: 6783,
        source: "Int[u_*v_^n_.,x_Symbol] :=
          With[{tmp=InverseFunctionOfLinear[u,x]},
          (-Discriminant[v,x]/(4*Coefficient[v,x,2]))^n/Coefficient[tmp[[1]],x,1]*
        \tSubst[Int[SimplifyIntegrand[SubstForInverseFunction[u,tmp,x]*Sech[x]^(2*(n+1)),x],x], x, tmp] /;
         Not[FalseQ[tmp]] && EqQ[Head[tmp],ArcTanh] && EqQ[Discriminant[v,x]*tmp[[1]]^2-D[v,x]^2,0]] /;
        QuadraticQ[v,x] && ILtQ[n,0] && PosQ[Discriminant[v,x]] && MatchQ[u,r_.*f_^w_ /; FreeQ[f,x]]",
        desc: "Integration by substitution",
        refs: [],
        pattern:  rubi_shared_pattern_56(symbols),
        with: [u__, v_, n_, x_],
        optional: [n_],
        when: {
            iltq!(n_, 0)
                && rubi_inverse_linear_quadratic_match(&u__, &v_, x_, RubiInverseKind::ArcTanh)
                    .is_some()
        },
        rhs: {
            let matched =
                rubi_inverse_linear_quadratic_match(&u__, &v_, x_, RubiInverseKind::ArcTanh).rubi_rhs();
            let substitution_guard = fresh_substitution_symbol().unwrap();
            let substitution_symbol = substitution_guard.symbol();
            let sub_atom = Atom::var(substitution_symbol);
            let payload = rubi_simplify_integrand(
                &(matched.transformed_u * sub_atom.sech().pow(Atom::num(2) * (&n_ + 1))),
                substitution_symbol,
            );
            let primitive = rubi_rhs_int(&payload, substitution_symbol);
            let prefactor = (-matched.discriminant / (Atom::num(4) * matched.quadratic_coeff)).pow(&n_)
                / matched.linear_slope;
            rubi_simp(
                &(prefactor
                    * rubi_subst(
                        &primitive,
                        substitution_symbol,
                        matched.inverse_function,
                    )),
                x_,
            )
        },
    ));
}

