#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn downvalues_6492_through_6692_are_registered_once_in_order() {
        let _ = symbol!("x");
        let mut rules = Vec::new();
        push_rules(&mut rules);
        let orders = rules
            .iter()
            .filter_map(|rule| rule.downvalue_order)
            .filter(|order| (6492..=6692).contains(order))
            .collect::<Vec<_>>();
        assert_eq!(orders, (6492..=6692).collect::<Vec<_>>());
    }
}

